import requests

      # Configuration
      LITELLM_SERVER_URL = 'https://bearborg.berkeley.edu:4433' # os.environ['LITE_LLM_SERVER']
      LITELLM_API_CREATE_USER = f"{LITELLM_SERVER_URL}/user/new"
      LITELLM_API_ISSUE_KEY = f"{LITELLM_SERVER_URL}/key/generate"
      LITELLM_API_GET_USERS = f"{LITELLM_SERVER_URL}/user/get_users"
      LITELLM_API_GET_USER_INFO = f"{LITELLM_SERVER_URL}/user/info"
      API_KEY = '[REDACTED]'# os.getenv("LITELLM_API_KEY")

      def get_all_users():
        response = requests.get(LITELLM_API_GET_USERS, headers={"Authorization": f"Bearer {API_KEY}"})
        if response.status_code == 200:
          user_list  = response.json()
          users = user_list['users']
          return [(user['user_email'], user['user_id']) for user in users]
        return []

      def get_user_id(user_email):
        users = get_all_users()
        for user in users:
          if user[0] == user_email:
            return user[1]
        return None

      def get_user_info(user_email):
        user_id  = get_user_id(user_email)
        if user_id is not None:
          response = requests.get(f'{LITELLM_API_GET_USER_INFO}?user_id={user_id}', headers={"Authorization": f"Bearer {API_KEY}"})
          if response.status_code == 200:
            return response.json()
          else:
            response.raise_for_status()    
        else:
          return None

      def create_litellm_user(user_email):
        """Create a user on the LiteLLM server."""
        headers = {
          "Authorization": f"Bearer {API_KEY}",
          "Content-Type": "application/json"
        }
        response = requests.post(LITELLM_API_CREATE_USER, headers=headers, json={"user_email": user_email})
        if response.status_code == 200:
          return response.json()
        else:
          response.raise_for_status()

      def issue_litellm_key(userid):
        """Issue an API key for the LiteLLM user."""
        headers = {
          "Authorization": f"Bearer {API_KEY}",
          "Content-Type": "application/json"
        }
        response = requests.post(LITELLM_API_ISSUE_KEY, headers=headers, json={"user_id": userid})
        if response.status_code == 200:
          api_key = response.json().get("key")
          return api_key
          # print(f"Issued API key for LiteLLM user '{userid}': {api_key}")
          # return api_key
        else:
          response.raise_for_status()
    
      def my_hook(spawner):
        print('In my_hook')
        username = spawner.user.name
        user_id = get_user_id(username)
        print(f'user id for {username} is {user_id}')
        if user_id is None:
          result = create_litellm_user(username)
          user_id = result["user_id"]
          print(f'Created user id for {username} {user_id}')
        key = issue_litellm_key(user_id)
        if spawner.environment is None:
          print("setting env vars")
          spawner.environment = {
            'LITELLM_SERVER': LITELLM_SERVER_URL,
            'LITELLM_API_KEY': key,
            'OPENAI_API_KEY': key,
            'OPENAI_API_BASE': f"{LITELLM_SERVER_URL}/v1",
          }
        else:
          print("setting env vars")
          spawner.environment['LITELLM_SERVER'] = LITELLM_SERVER_URL
          spawner.environment['LITELLM_API_KEY'] = key
          spawner.environment['OPENAI_API_KEY'] = key
          spawner.environment['OPENAI_API_BASE'] = f"{LITELLM_SERVER_URL}/v1"


        
      c.Spawner.pre_spawn_hook = my_hook
